/**
 * Return all templates for a given stakeholder / variant combination.
 * Returns an empty array when the combination doesn't exist.
 */
export function getTemplates(
  stakeholderId: string,
  variant: string
): ResponseTemplate[] {
  return RESPONSE_TEMPLATES[stakeholderId]?.[variant] ?? [];
}
